INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'معهد تدريب معتمد في حفر الباطن: دبلومات ودورات معهد السمو للرجال والنساء', 'معهد-تدريب-معتمد-في-حفر-الباطن', 'تبحث عن معهد تدريب معتمد في حفر الباطن؟ تعرّف على معهد السمو المتخصص العالي للتدريب: دبلومات ودورات معتمدة من المؤسسة العامة للتدريب التقني والمهني، حضوريًا في حفر الباطن وعن بُعد في جميع أنحاء المملكة.', '<p>معهد السمو المتخصص العالي للتدريب معهد تدريب أهلي في <strong>حفر الباطن</strong> بالمنطقة الشرقية، يقدّم <strong>دبلومات ودورات تدريبية معتمدة من المؤسسة العامة للتدريب التقني والمهني</strong> للرجال والنساء، حضوريًا في مقر المعهد وعن بُعد لكل مناطق المملكة، وقريبًا في الدمام والرياض والمدينة المنورة وخميس مشيط.</p><h2>لماذا يختار المتدربون معهد السمو؟</h2><ul><li>شهادات معتمدة من المؤسسة العامة للتدريب التقني والمهني يمكن الاستفادة منها في التوظيف والترقية.</li><li>دبلومات تؤهلك لسوق العمل مباشرة بعد الثانوية العامة، ودورات قصيرة لتطوير المهارات.</li><li>خيار الدراسة حضوريًا في حفر الباطن أو عن بُعد من أي مدينة في المملكة.</li><li>برامج للرجال والنساء بمواعيد مناسبة للعاملين والطلاب.</li></ul><h2>الدبلومات المعتمدة في معهد السمو</h2><ul><li><a href="/programs/دبلوم-إدارة-التمريض">دبلوم إدارة التمريض</a></li><li><a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a></li><li><a href="/programs/ادارة-الموارد-البشرية-عن-بعد">دبلوم إدارة الموارد البشرية عن بُعد</a></li><li><a href="/programs/دبلوم-إدارة-المستشفيات">دبلوم إدارة المستشفيات والخدمات الصحية</a></li><li><a href="/programs/دبلوم-الإدارة-المكتبية">دبلوم الإدارة المكتبية</a></li><li><a href="/programs/دبلوم-القانون">دبلوم القانون</a></li><li><a href="/programs/الذكاء-الاصطناعي">دبلوم الذكاء الاصطناعي</a></li></ul><h2>الدورات التأهيلية والتطويرية</h2><ul><li><a href="/programs/دورة-إستخدام-الحاسب-الألي-في-الأعمال-المكتبية">دورة الحاسب الآلي في الأعمال المكتبية</a></li><li><a href="/programs/دورة-إدخال-البيانات-ومعالجة-النصوص">دورة إدخال البيانات ومعالجة النصوص</a></li><li><a href="/programs/دورة-الإدارة-المكتبية">دورة الإدارة المكتبية</a></li><li><a href="/programs/دورة-الإدارة-المكتبية-المتقدمة">دورة الإدارة المكتبية المتقدمة</a></li><li><a href="/programs/دورة-اللغة-الإنجليزية">دورة اللغة الإنجليزية</a></li></ul><p>تصفح <a href="/programs">جميع البرامج</a> لمعرفة مدة كل برنامج وساعاته المعتمدة ومجالات العمل بعد التخرج.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/47f7e38be3049e0e0f74.webp', 'أدلة ونصائح', CURDATE(), 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'معهد-تدريب-معتمد-في-حفر-الباطن');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلومات بعد الثانوي في السعودية: كيف تختار الدبلوم المعتمد المناسب لسوق العمل؟', 'دبلومات-بعد-الثانوي', 'أنهيت الثانوية العامة وتفكر في دبلوم؟ دليل عملي لاختيار دبلوم معتمد بعد الثانوي في السعودية: الاعتماد، المدة، مجالات العمل، والدراسة حضوريًا أو عن بُعد.', '<p>الدبلوم بعد الثانوي طريق سريع إلى سوق العمل: مدة أقصر من البكالوريوس، وتركيز على المهارات التي يطلبها أصحاب العمل، وشهادة معتمدة تُقبل في التوظيف. لكن ليس كل دبلوم مثل غيره، لذلك إليك ما يجب أن تسأل عنه قبل التسجيل.</p><h2>1) هل الدبلوم معتمد؟</h2><p>تأكد أن المعهد مرخّص وأن البرنامج معتمد من <strong>المؤسسة العامة للتدريب التقني والمهني</strong>. الدبلومات في معهد السمو معتمدة من المؤسسة، ويمكنك التحقق من تراخيص المعاهد الأهلية عبر بوابة التدريب الأهلي التابعة للمؤسسة.</p><h2>2) هل يناسب المجال سوق العمل؟</h2><p>اختر مجالًا عليه طلب واضح: الإدارة والموارد البشرية والقطاع الصحي والقانون والتقنية من أكثر المجالات طلبًا في المملكة.</p><ul><li><a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a>: شؤون الموظفين والتوظيف والرواتب في الشركات والجهات.</li><li><a href="/programs/دبلوم-إدارة-التمريض">دبلوم إدارة التمريض</a> و<a href="/programs/دبلوم-إدارة-المستشفيات">دبلوم إدارة المستشفيات والخدمات الصحية</a>: إدارة الأقسام والخدمات في المستشفيات والمراكز الصحية.</li><li><a href="/programs/دبلوم-القانون">دبلوم القانون</a>: الأنظمة والعقود وشؤون العمل في المكاتب والشركات.</li><li><a href="/programs/الذكاء-الاصطناعي">دبلوم الذكاء الاصطناعي</a>: مهارات التقنية الأحدث والأكثر طلبًا.</li><li><a href="/programs/دبلوم-الإدارة-المكتبية">دبلوم الإدارة المكتبية</a>: السكرتارية وإدارة المكاتب والأرشفة.</li></ul><h2>3) حضوري أم عن بُعد؟</h2><p>إذا كنت في حفر الباطن يمكنك الدراسة حضوريًا في المعهد، وإذا كنت في مدينة أخرى أو تعمل، فبعض البرامج متاحة <strong>عن بُعد</strong> مثل <a href="/programs/ادارة-الموارد-البشرية-عن-بعد">دبلوم إدارة الموارد البشرية عن بُعد</a>.</p><h2>4) المدة والساعات المعتمدة</h2><p>اطّلع على صفحة كل برنامج لمعرفة مدته وساعاته المعتمدة وعدد مستوياته. ابدأ من صفحة <a href="/programs/type/diploma">الدبلومات المعتمدة</a>.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/7a9682362b156a4891d1.webp', 'أدلة ونصائح', CURDATE(), 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دبلومات-بعد-الثانوي');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلوم عن بعد معتمد في السعودية: الدليل الكامل للدراسة عن بُعد بشهادة معتمدة', 'دبلوم-عن-بعد-معتمد', 'هل يمكن الحصول على دبلوم معتمد وأنت تدرس عن بعد؟ تعرّف على الدبلومات عن بعد المعتمدة من المؤسسة العامة للتدريب التقني والمهني، وكيف تدرس من أي مدينة في المملكة مع معهد السمو.', '<p>الدراسة عن بُعد أصبحت خيارًا معتمدًا لكثير من الموظفين والأمهات والمقيمين خارج المدن الكبرى. المهم أن يكون <strong>الدبلوم عن بعد معتمدًا</strong> من المؤسسة العامة للتدريب التقني والمهني، وأن تكون الدراسة منظمة بمحاضرات واختبارات ومتابعة حقيقية.</p><h2>ما الدبلومات المتاحة عن بُعد في معهد السمو؟</h2><ul><li><a href="/programs/ادارة-الموارد-البشرية-عن-بعد">دبلوم إدارة الموارد البشرية عن بُعد</a></li><li>برامج أخرى تُتاح عن بُعد حسب الدفعات؛ تجد طريقة الدراسة مكتوبة في صفحة كل برنامج ضمن <a href="/programs">جميع البرامج</a>.</li></ul><h2>مميزات الدبلوم عن بُعد</h2><ul><li>تدرس من أي مدينة في المملكة: الرياض، الدمام، جدة، المدينة المنورة، خميس مشيط وغيرها.</li><li>مناسب للموظفين والموظفات وربات البيوت.</li><li>نفس الشهادة المعتمدة التي يحصل عليها المتدرب الحضوري.</li></ul><h2>كيف تتأكد أن الدبلوم عن بعد معتمد؟</h2><p>اسأل عن جهة الاعتماد ورقم ترخيص المعهد، وتحقق منه في بوابة التدريب الأهلي التابعة للمؤسسة العامة للتدريب التقني والمهني. معهد السمو معهد مرخّص ودبلوماته معتمدة من المؤسسة.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/4e1b29ed7cc5434060f0.webp', 'أدلة ونصائح', CURDATE(), 1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دبلوم-عن-بعد-معتمد');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'كيف تتحقق من ترخيص معهد التدريب واعتماد الشهادة في السعودية قبل التسجيل؟', 'كيف-تتحقق-من-ترخيص-معهد-تدريب', 'قبل أن تدفع رسوم أي دورة أو دبلوم: خطوات بسيطة للتأكد أن المعهد مرخّص من المؤسسة العامة للتدريب التقني والمهني وأن شهادتك ستكون معتمدة.', '<p>الشهادة المعتمدة هي ما يصنع الفرق عند التقديم على وظيفة أو طلب ترقية. لذلك قبل التسجيل في أي معهد تدريب تأكد من ثلاثة أمور:</p><h2>1) ترخيص المعهد</h2><p>المعاهد الأهلية في المملكة تعمل بترخيص من <strong>المؤسسة العامة للتدريب التقني والمهني</strong>. يمكنك البحث عن اسم المعهد في خدمة «الاستعلام عن المعاهد المرخصة» في منظومة التدريب الأهلي التابعة للمؤسسة.</p><h2>2) اعتماد البرنامج نفسه</h2><p>اسأل: هل هذا الدبلوم أو هذه الدورة معتمدة من المؤسسة؟ وما عدد الساعات المعتمدة؟ في معهد السمو تجد جهة الاعتماد والساعات مكتوبة في صفحة كل برنامج.</p><h2>3) نوع الشهادة</h2><ul><li><strong>دبلوم</strong>: برنامج طويل بمستويات ومقررات، يؤهل لوظيفة في مجال محدد.</li><li><strong>دورة تأهيلية</strong>: مهارة عملية أساسية مثل الحاسب وإدخال البيانات.</li><li><strong>دورة تطويرية</strong>: تطوير مهارة لمن يعمل أصلًا، مثل اللغة الإنجليزية.</li></ul><p>اطلع على <a href="/programs/type/diploma">الدبلومات المعتمدة</a> و<a href="/programs/type/qualifying">الدورات التأهيلية</a> في معهد السمو.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/7a9682362b156a4891d1.webp', 'أدلة ونصائح', CURDATE(), 1, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'كيف-تتحقق-من-ترخيص-معهد-تدريب');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'ما الفرق بين الدبلوم والدورة التأهيلية والدورة التطويرية؟ وأي شهادة تحتاجها للوظيفة؟', 'الفرق-بين-الدبلوم-والدورة-والشهادة-المعتمدة', 'دبلوم أم دورة؟ شرح مبسّط للفرق بين الدبلوم المعتمد والدورة التأهيلية والدورة التطويرية، ومتى تحتاج كل واحدة منها في مسارك المهني في السعودية.', '<h2>الدبلوم المعتمد</h2><p>برنامج تدريبي متكامل يمتد عادة لسنة أو أكثر، مقسّم إلى مستويات ومقررات، وينتهي بشهادة دبلوم معتمدة. يناسب من يريد دخول مجال جديد أو بناء مسار مهني كامل، مثل <a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a> و<a href="/programs/دبلوم-القانون">دبلوم القانون</a>.</p><h2>الدورة التأهيلية</h2><p>تؤهلك لمهارة عملية أساسية يطلبها سوق العمل في وقت قصير، مثل <a href="/programs/دورة-إستخدام-الحاسب-الألي-في-الأعمال-المكتبية">دورة الحاسب الآلي في الأعمال المكتبية</a> و<a href="/programs/دورة-إدخال-البيانات-ومعالجة-النصوص">دورة إدخال البيانات ومعالجة النصوص</a> و<a href="/programs/دورة-الإدارة-المكتبية">دورة الإدارة المكتبية</a>.</p><h2>الدورة التطويرية</h2><p>لمن يعمل ويريد تطوير مهارة محددة، مثل <a href="/programs/دورة-اللغة-الإنجليزية">دورة اللغة الإنجليزية</a>.</p><h2>أيها أختار؟</h2><ul><li>بعد الثانوية وتريد وظيفة في مجال محدد: ابدأ بدبلوم.</li><li>تحتاج مهارة سريعة لوظيفة مكتبية: دورة تأهيلية.</li><li>موظف وتريد الترقية أو مهارة إضافية: دورة تطويرية أو دبلوم في مجالك.</li></ul><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/dd42419e6a5bb162086b.webp', 'أدلة ونصائح', CURDATE(), 1, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'الفرق-بين-الدبلوم-والدورة-والشهادة-المعتمدة');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلوم إدارة الموارد البشرية: ماذا تدرس، وأين تعمل بعد التخرج؟', 'دبلوم-ادارة-الموارد-البشرية-ماذا-تدرس-واين-تعمل', 'كل ما تريد معرفته عن دبلوم إدارة الموارد البشرية المعتمد: المواد، المهارات، الوظائف المتاحة في السعودية، والدراسة حضوريًا في حفر الباطن أو عن بُعد.', '<p>الموارد البشرية من أكثر المجالات طلبًا في الشركات والجهات السعودية، فكل منشأة تحتاج من يدير التوظيف وشؤون الموظفين والرواتب والتدريب ويطبّق نظام العمل.</p><h2>ماذا تدرس في دبلوم إدارة الموارد البشرية؟</h2><ul><li>تخطيط القوى العاملة والاستقطاب والتوظيف.</li><li>شؤون الموظفين والرواتب والإجازات.</li><li>تقييم الأداء والتدريب والتطوير.</li><li>نظام العمل وحقوق العامل وصاحب العمل.</li><li>مهارات التواصل والتقارير الإدارية.</li></ul><h2>أين تعمل بعد التخرج؟</h2><ul><li>أخصائي أو مساعد موارد بشرية.</li><li>موظف توظيف واستقطاب.</li><li>موظف شؤون موظفين ورواتب.</li><li>منسق تدريب وتطوير.</li></ul><h2>حضوري أو عن بُعد</h2><p>يمكنك الدراسة حضوريًا في حفر الباطن عبر <a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a>، أو من أي مدينة في المملكة عبر <a href="/programs/ادارة-الموارد-البشرية-عن-بعد">دبلوم إدارة الموارد البشرية عن بُعد</a>.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/4b4c08fd3cd9b34f165e.webp', 'أدلة ونصائح', CURDATE(), 1, 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دبلوم-ادارة-الموارد-البشرية-ماذا-تدرس-واين-تعمل');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلوم إدارة التمريض: من العمل التمريضي إلى قيادة الأقسام الصحية', 'دبلوم-ادارة-التمريض-من-التمريض-الى-القيادة', 'دبلوم إدارة التمريض المعتمد للممرضين والممرضات والعاملين في القطاع الصحي: قيادة الفرق، جودة الرعاية، سلامة المرضى، وإدارة أقسام التمريض.', '<p>يحتاج القطاع الصحي في المملكة إلى قيادات تمريضية تجمع بين الخبرة السريرية ومهارات الإدارة. <strong>دبلوم إدارة التمريض</strong> يمنحك هذه المهارات لتنتقل من العمل اليومي إلى الإشراف وقيادة الأقسام.</p><h2>ماذا ستتعلم؟</h2><ul><li>أسس الإدارة والقيادة في التمريض.</li><li>تخطيط القوى العاملة وتوزيع المناوبات وتقييم الأداء.</li><li>معايير جودة الرعاية وسلامة المرضى ومكافحة العدوى.</li><li>إدارة الموارد والمستلزمات وميزانية القسم.</li><li>التواصل الفعّال وإدارة الأزمات.</li><li>أخلاقيات المهنة وأنظمة العمل الصحي.</li></ul><h2>برامج صحية أخرى</h2><p>إذا كنت تهتم بإدارة المنشآت الصحية بشكل أوسع فاطّلع على <a href="/programs/دبلوم-إدارة-المستشفيات">دبلوم إدارة المستشفيات والخدمات الصحية</a>. وتفاصيل دبلوم التمريض كاملة في صفحة <a href="/programs/دبلوم-إدارة-التمريض">دبلوم إدارة التمريض</a>.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/70796f9b620f404215ef.webp', 'أدلة ونصائح', CURDATE(), 1, 6 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دبلوم-ادارة-التمريض-من-التمريض-الى-القيادة');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلوم القانون في السعودية: المواد ومجالات العمل واستكمال البكالوريوس', 'دبلوم-القانون-في-السعودية', 'دبلوم القانون المعتمد في معهد السمو: مفهوم القانون ومصادره، نظام العمل، المعاملات المدنية والعقود، 84 ساعة معتمدة مع إمكانية استكمال البكالوريوس.', '<p>يزداد الطلب على من يفهم الأنظمة والعقود وشؤون العمل في الشركات والمكاتب. <strong>دبلوم القانون</strong> يمنحك أساسًا قانونيًا عمليًا يفتح لك مجالات عمل متعددة.</p><h2>ماذا تدرس؟</h2><ul><li>مفهوم القانون ومصادره وأقسامه: القانون العام والخاص.</li><li>نظام العمل وحقوق وواجبات العامل وصاحب العمل وتسوية المنازعات العمالية.</li><li>المعاملات المدنية: العقود والمسؤولية المدنية والحقوق الشخصية والعينية.</li></ul><h2>مميزات الدبلوم</h2><ul><li>84 ساعة معتمدة.</li><li>يقبل استكمال درجة البكالوريوس.</li><li>مصنف من وزارة الموارد البشرية.</li></ul><p>التفاصيل والتسجيل في صفحة <a href="/programs/دبلوم-القانون">دبلوم القانون</a>.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/b51bf379c1755bd3a9d3.webp', 'أدلة ونصائح', CURDATE(), 1, 7 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دبلوم-القانون-في-السعودية');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلوم الذكاء الاصطناعي: تعلّم المهارة الأكثر طلبًا في سوق العمل السعودي', 'دبلوم-الذكاء-الاصطناعي', 'دبلوم الذكاء الاصطناعي في معهد السمو: التعلم الآلي والتعلم العميق وتحليل البيانات وبناء الحلول الذكية، 74 ساعة معتمدة.', '<p>الذكاء الاصطناعي لم يعد مجالًا للمبرمجين فقط؛ فهو يدخل اليوم في الصحة والتعليم والأعمال والتسويق، وأصبحت مهاراته مطلوبة في كل منشأة تتجه للتحول الرقمي ضمن رؤية المملكة 2030.</p><h2>ماذا ستتعلم؟</h2><ul><li>المفاهيم الأساسية: التعلم الآلي (Machine Learning) والتعلم العميق (Deep Learning).</li><li>تحليل البيانات الكبيرة والتنبؤ بالسلوكيات المستقبلية.</li><li>مجالات تطبيق الذكاء الاصطناعي في الصحة والتعليم والأعمال والأمن والصناعة والتسويق.</li><li>بناء حلول ذكية مثل روبوتات الدردشة وأنظمة التوصية وتصنيف الصور والنصوص.</li></ul><p>74 ساعة معتمدة. التفاصيل في صفحة <a href="/programs/الذكاء-الاصطناعي">دبلوم الذكاء الاصطناعي</a>.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/a3541f6c60a8bb47071c.webp', 'أدلة ونصائح', CURDATE(), 1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دبلوم-الذكاء-الاصطناعي');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'كيف تساعدك الشهادات والدورات المعتمدة في الحصول على وظيفة في السعودية؟', 'شهادة-معتمدة-تساعدك-في-الوظيفة', 'تبحث عن وظيفة؟ لماذا يطلب أصحاب العمل شهادات ودورات معتمدة، وما المهارات التي تزيد فرصتك في التوظيف، وكيف تبدأ مع برامج معهد السمو.', '<p>في سوق عمل تنافسي، الشهادة المعتمدة والمهارات العملية هي ما يميز سيرتك الذاتية. كثير من الوظائف الإدارية والمكتبية والصحية تطلب دبلومًا أو دورات معتمدة إلى جانب المؤهل الدراسي.</p><h2>مهارات يطلبها أصحاب العمل</h2><ul><li>استخدام الحاسب والبرامج المكتبية: <a href="/programs/دورة-إستخدام-الحاسب-الألي-في-الأعمال-المكتبية">دورة الحاسب الآلي في الأعمال المكتبية</a>.</li><li>إدخال البيانات ومعالجة النصوص بدقة: <a href="/programs/دورة-إدخال-البيانات-ومعالجة-النصوص">دورة إدخال البيانات ومعالجة النصوص</a>.</li><li>اللغة الإنجليزية للعمل: <a href="/programs/دورة-اللغة-الإنجليزية">دورة اللغة الإنجليزية</a>.</li><li>تنظيم المكاتب والسكرتارية: <a href="/programs/دورة-الإدارة-المكتبية">دورة الإدارة المكتبية</a> و<a href="/programs/دورة-الإدارة-المكتبية-المتقدمة">دورة الإدارة المكتبية المتقدمة</a>.</li></ul><h2>دبلومات تفتح مسارًا وظيفيًا كاملًا</h2><ul><li><a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a></li><li><a href="/programs/دبلوم-الإدارة-المكتبية">دبلوم الإدارة المكتبية</a></li><li><a href="/programs/دبلوم-إدارة-التمريض">دبلوم إدارة التمريض</a></li><li><a href="/programs/دبلوم-إدارة-المستشفيات">دبلوم إدارة المستشفيات والخدمات الصحية</a></li><li><a href="/programs/دبلوم-القانون">دبلوم القانون</a></li><li><a href="/programs/الذكاء-الاصطناعي">دبلوم الذكاء الاصطناعي</a></li></ul><h2>نصائح سريعة</h2><ul><li>اختر برنامجًا معتمدًا من المؤسسة العامة للتدريب التقني والمهني.</li><li>أضف الشهادة وساعاتها المعتمدة في سيرتك الذاتية وحساباتك المهنية.</li><li>سجّل في منصات التوظيف الوطنية وتابع الفرص في مجالك.</li></ul><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/47f7e38be3049e0e0f74.webp', 'أدلة ونصائح', CURDATE(), 1, 9 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'شهادة-معتمدة-تساعدك-في-الوظيفة');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دورات الحاسب الآلي وإدخال البيانات واللغة الإنجليزية: مهارات كل وظيفة مكتبية', 'دورات-الحاسب-والانجليزي-وادخال-البيانات', 'دورات قصيرة معتمدة في حفر الباطن وعن بعد: الحاسب الآلي في الأعمال المكتبية، إدخال البيانات ومعالجة النصوص، الإدارة المكتبية، واللغة الإنجليزية.', '<p>إذا كنت تريد وظيفة مكتبية أو تطوير أدائك في عملك الحالي، فهذه الدورات القصيرة تمنحك المهارات الأساسية بسرعة وبشهادة معتمدة.</p><h2>الدورات المتاحة</h2><ul><li><a href="/programs/دورة-إستخدام-الحاسب-الألي-في-الأعمال-المكتبية">دورة الحاسب الآلي في الأعمال المكتبية</a>: أنظمة التشغيل والبرامج المكتبية والبريد والإنترنت.</li><li><a href="/programs/دورة-إدخال-البيانات-ومعالجة-النصوص">دورة إدخال البيانات ومعالجة النصوص</a>: الكتابة السريعة الدقيقة والتعامل مع برامج معالجة النصوص.</li><li><a href="/programs/دورة-الإدارة-المكتبية">دورة الإدارة المكتبية</a>: تنظيم المواعيد والأرشفة والمراسلات.</li><li><a href="/programs/دورة-الإدارة-المكتبية-المتقدمة">دورة الإدارة المكتبية المتقدمة</a>: التخطيط والتنسيق وإدارة الوقت والتقنيات الحديثة في المكتب.</li><li><a href="/programs/دورة-اللغة-الإنجليزية">دورة اللغة الإنجليزية</a>: المحادثة والكتابة والمفردات لبيئة العمل.</li></ul><p>كل الدورات في صفحة <a href="/programs/type/qualifying">الدورات التأهيلية</a>.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/e5ecf41e4a53629a0014.webp', 'أدلة ونصائح', CURDATE(), 1, 10 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'دورات-الحاسب-والانجليزي-وادخال-البيانات');
INSERT INTO posts (title, slug, excerpt, body, cover, category, published_at, is_published, sort) SELECT 'دبلومات ودورات معتمدة للنساء في حفر الباطن وعن بُعد', 'تدريب-ودبلومات-للنساء-في-حفر-الباطن', 'معاهد حفر الباطن للنساء: دبلومات ودورات معتمدة للسيدات في معهد السمو، حضوريًا في حفر الباطن أو عن بعد من المنزل، في الإدارة والموارد البشرية والقطاع الصحي والقانون.', '<p>يقدّم معهد السمو برامجه <strong>للنساء</strong> كما للرجال، حضوريًا في حفر الباطن أو <strong>عن بُعد</strong> لمن تفضّل الدراسة من المنزل، بشهادات معتمدة من المؤسسة العامة للتدريب التقني والمهني.</p><h2>برامج مناسبة لسوق عمل المرأة</h2><ul><li><a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a></li><li><a href="/programs/ادارة-الموارد-البشرية-عن-بعد">دبلوم إدارة الموارد البشرية عن بُعد</a></li><li><a href="/programs/دبلوم-الإدارة-المكتبية">دبلوم الإدارة المكتبية</a></li><li><a href="/programs/دبلوم-إدارة-التمريض">دبلوم إدارة التمريض</a></li><li><a href="/programs/دبلوم-إدارة-المستشفيات">دبلوم إدارة المستشفيات والخدمات الصحية</a></li><li><a href="/programs/دبلوم-القانون">دبلوم القانون</a></li><li><a href="/programs/الذكاء-الاصطناعي">دبلوم الذكاء الاصطناعي</a></li></ul><h2>دورات قصيرة</h2><ul><li><a href="/programs/دورة-إستخدام-الحاسب-الألي-في-الأعمال-المكتبية">دورة الحاسب الآلي في الأعمال المكتبية</a></li><li><a href="/programs/دورة-إدخال-البيانات-ومعالجة-النصوص">دورة إدخال البيانات ومعالجة النصوص</a></li><li><a href="/programs/دورة-اللغة-الإنجليزية">دورة اللغة الإنجليزية</a></li></ul><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>', '/uploads/2026/11/4e1b29ed7cc5434060f0.webp', 'أدلة ونصائح', CURDATE(), 1, 11 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM posts WHERE slug = 'تدريب-ودبلومات-للنساء-في-حفر-الباطن');
